SINA_SMART["genetics1-rna-processing"] = {"lecture":"genetics1-rna-processing","title":"Post-transcriptional RNA processing","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"genetics1-rna-processing:e0","text":"Processing: capping, polyadenylation, splicing, editing, export.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-rna-processing:e10","text":"Prokaryotes: no introns, no cap, coupled transcription-translation.","topic":"The big picture","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-rna-processing:e1","text":"Cap = m⁷G via 5′-5′ triphosphate, added at ~20-30 nt.","topic":"5′ cap and poly(A) tail","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-rna-processing:e2","text":"Cap enzymes: triphosphatase, guanylyltransferase, methyltransferase.","topic":"5′ cap and poly(A) tail","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-rna-processing:e3","text":"Cap: protection from 5′ exonucleases, export, translation start.","topic":"5′ cap and poly(A) tail","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-rna-processing:e4","text":"Poly(A): CPSF (AAUAAA) + CstF (GU-rich) cleave; PAP adds ~200 A; PABP binds.","topic":"5′ cap and poly(A) tail","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-rna-processing:e5","text":"Spliceosome snRNPs: U1, U2, U4/U6, U5; U2 binds branch point.","topic":"Splicing","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-rna-processing:e6","text":"Branch-point A 2′-OH attacks 5′ site → lariat; exon 3′-OH attacks 3′ site.","topic":"Splicing","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-rna-processing:e7","text":"Alternative splicing: calcitonin/CGRP, Bcl-xL/xS, SMN1/SMN2.","topic":"Splicing","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-rna-processing:e8","text":"Editing: A→I (ADAR), C→U (APOBEC).","topic":"Editing, export and pseudogenes","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"genetics1-rna-processing:e9","text":"Processed pseudogenes: intronless copies by retrotransposition.","topic":"Editing, export and pseudogenes","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"vgdq2s":"a","r28jcl":"a","885zj5":"a","1v9uqyl":"a","19e1ag5":"a","ikj5dy":"a","143b1yy":"a","tfi17t":"a","d4xysb":"a","4av1fg":"a","1048y0x":"a","1x6o2ag":"a","1tt6sk":"a","1hpckfr":"a","wrd5tg":"a","1394yi":"a"},"mapCounts":{"verified":0,"auto":16,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"genetics1-rna-processing:e0":{"s":0,"u":["Processing: capping, polyadenylation, splicing, editing, export.","In eukaryotes, transcription makes a pre-mRNA that must be processed before export: 5′ capping , polyadenylation , splicing , sometimes RNA editing , then nuclear export ."],"dp":[]},"genetics1-rna-processing:e10":{"s":0,"u":["Prokaryotes: no introns, no cap, coupled transcription-translation.","Prokaryotes have no introns, no cap, rarely a poly(A) tail , and couple transcription and translation in the cytoplasm."],"dp":[{"h":"Why the cap and tail protect mRNA","t":"Cells are full of exonucleases that chew RNA from either end. The inverted 5′-5′ cap and the long poly(A) tail with its binding proteins shield both ends, so an mRNA survives long enough to be translated many times. As the tail shortens with time, the mRNA becomes vulnerable and is degraded, which sets its lifespan. Source: the lecture's cap and polyadenylation slides."}]},"genetics1-rna-processing:e1":{"s":1,"u":["Cap = m⁷G via 5′-5′ triphosphate, added at ~20-30 nt.","Cap : a 7-methylguanosine (m⁷G) joined by an unusual 5′-5′ triphosphate bond, added co-transcriptionally when the RNA is ~20-30 nt: RNA triphosphatase removes the γ-phosphate, guanylyltransferase adds GMP from GTP, methyltransferase methylates guanine N7."],"dp":[]},"genetics1-rna-processing:e2":{"s":1,"u":["Cap enzymes: triphosphatase, guanylyltransferase, methyltransferase.","Cap : a 7-methylguanosine (m⁷G) joined by an unusual 5′-5′ triphosphate bond, added co-transcriptionally when the RNA is ~20-30 nt: RNA triphosphatase removes the γ-phosphate, guanylyltransferase adds GMP from GTP, methyltransferase methylates guanine N7."],"dp":[]},"genetics1-rna-processing:e3":{"s":1,"u":["Cap: protection from 5′ exonucleases, export, translation start.","Functions: protects from 3′→5′ exonucleases, aids export, boosts translation and stability.","Functions: protects from 5′→3′ exonucleases, needed for export, helps ribosome binding (translation initiation) and first-intron splicing."],"dp":[]},"genetics1-rna-processing:e4":{"s":1,"u":["Poly(A): CPSF (AAUAAA) + CstF (GU-rich) cleave; PAP adds ~200 A; PABP binds.","Poly(A) tail : pre-mRNA is cleaved downstream of AAUAAA ; CPSF binds AAUAAA, CstF binds the downstream GU-rich region (with CFIm, CFIIm); poly(A) polymerase adds ~ 200 A without a template; PABP binds the tail, stabilises it and regulates length."],"dp":[]},"genetics1-rna-processing:e5":{"s":2,"u":["Spliceosome snRNPs: U1, U2, U4/U6, U5; U2 binds branch point.","The spliceosome is an RNA-protein complex of snRNAs + proteins ( snRNPs U1, U2, U4/U6, U5 ) recognising the 5′ splice site, the 3′ splice site and the branch point (recognised by U2)."],"dp":[]},"genetics1-rna-processing:e6":{"s":2,"u":["Branch-point A 2′-OH attacks 5′ site → lariat; exon 3′-OH attacks 3′ site.","Two transesterifications : (1) the 2′-OH of the branch-point adenine attacks the 5′ splice site, forming a lariat ; (2) the 3′-OH of the upstream exon attacks the 3′ splice site, joining exons and releasing the intron for degradation.","The spliceosome is an RNA-protein complex of snRNAs + proteins ( snRNPs U1, U2, U4/U6, U5 ) recognising the 5′ splice site, the 3′ splice site and the branch point (recognised by U2)."],"dp":[]},"genetics1-rna-processing:e7":{"s":2,"u":["Alternative splicing: calcitonin/CGRP, Bcl-xL/xS, SMN1/SMN2.","Examples: fibronectin (plasma vs tissue), calcitonin vs CGRP (thyroid vs nervous system), tropomyosin (muscle types), Bcl-xL vs Bcl-xS (anti- vs pro-apoptotic), CD44 (>20 isoforms), Dscam (thousands), SMN1/SMN2 (spinal muscular atrophy).","Alternative splicing : one pre-mRNA gives several isoforms by exon skipping, alternative 5′/3′ sites, intron retention or mutually exclusive exons, regulated by SR proteins and hnRNPs."],"dp":[{"h":"Why one gene can make several proteins","t":"About 20,000 human genes produce far more distinct proteins than that, largely because alternative splicing mixes and matches exons. The same calcitonin gene gives a calcium-regulating hormone in the thyroid and a pain-signalling peptide in neurons; the Bcl-x gene gives either a survival or a death signal. Which isoform is made depends on splicing factors present in each tissue. Source: the lecture's alternative splicing table."}]},"genetics1-rna-processing:e8":{"s":3,"u":["Editing: A→I (ADAR), C→U (APOBEC).","RNA editing changes individual bases after transcription: A→I (inosine = hypoxanthine; by ADAR , e.g. glutamate receptor channel properties) and C→U (by APOBEC )."],"dp":[]},"genetics1-rna-processing:e9":{"s":3,"u":["Processed pseudogenes: intronless copies by retrotransposition.","Processed pseudogenes : non-functional gene copies without introns or regulatory sequences, formed by retrotransposition of mRNA (also tRNA, snRNA) with LINE ORF1/ORF2 proteins."],"dp":[]}},"meta":{"vgdq2s":{"a":"recall","vg":"genetics1-rna-processing:e1/recall/1"},"r28jcl":{"a":"recall","vg":"genetics1-rna-processing:e1/recall/2"},"885zj5":{"a":"recall","vg":"genetics1-rna-processing:e2/recall/1"},"1v9uqyl":{"a":"recall","vg":"genetics1-rna-processing:e10/recall/1"},"19e1ag5":{"a":"recall","vg":"genetics1-rna-processing:e4/recall/1"},"ikj5dy":{"a":"recall","vg":"genetics1-rna-processing:e4/recall/2"},"143b1yy":{"a":"recall","vg":"genetics1-rna-processing:e0/recall/1"},"tfi17t":{"a":"recall","vg":"genetics1-rna-processing:e5/recall/1"},"d4xysb":{"a":"recall","vg":"genetics1-rna-processing:e5/recall/2"},"4av1fg":{"a":"recall","vg":"genetics1-rna-processing:e10/recall/2"},"1048y0x":{"a":"recall","vg":"genetics1-rna-processing:e7/recall/1"},"1x6o2ag":{"a":"recall","vg":"genetics1-rna-processing:e7/recall/2"},"1tt6sk":{"a":"recall","vg":"genetics1-rna-processing:e7/recall/3"},"1hpckfr":{"a":"recall","vg":"genetics1-rna-processing:e8/recall/1"},"wrd5tg":{"a":"recall","vg":"genetics1-rna-processing:e9/recall/1"},"1394yi":{"a":"recall","vg":"genetics1-rna-processing:e10/recall/3"}},"explRev":"d6a7ab72d717"};
